package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSwDraft6 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_sharri_ma_amiltu" to DuaText("Kimbilio kutokana na Uovu wa Matendo Yangu", "Ewe Mwenyezi Mungu, najikinga Kwako kutokana na shari ya niliyoyafanya na shari ya yale ambayo sikuyafanya.", "Dua ya Mtume ﷺ, kwa mujibu wa Aisha (RA).", "Ulinzi dhidi ya matokeo ya yote yaliyofanywa na yale ambayo yaliachwa bila kufanywa."),
        "dua_jahdil_bala" to DuaText("Kimbilio kutoka kwa Majaribu Makali", "Ewe Mwenyezi Mungu, mimi najikinga Kwako kutokana na mitihani mikali, na kupatwa na dhiki, na hukumu mbaya na shari ya maadui.", "Kimbilio kutoka kwa majaribu makali na shangwe za maadui.", "Mtume ﷺ aliomba hifadhi kutokana na mambo haya manne."),
        "dua_fitnat_ghina_faqr" to DuaText("Kimbilio kutoka kwa Majaribu ya Utajiri na Umaskini", "Ewe Mwenyezi Mungu, najikinga Kwako na uvivu na uzee, na dhambi na deni, na mtihani na adhabu ya kaburi, na mtihani na adhabu ya Moto, na shari ya mtihani wa mali, na mtihani wa ufukara.", "Makimbilio ya mitihani ya kaburi, Jahannam, mali na umasikini (sehemu ya dua).", "Dua ya kina ya kimbilio kutoka kwa Mtume ﷺ."),
        "dua_kufr_faqr" to DuaText("Kimbilio kutoka kwa Ukafiri na Umaskini", "Ewe Mwenyezi Mungu, najikinga Kwako kutokana na ukafiri na umasikini, na najikinga Kwako kutokana na adhabu ya kaburi. Hapana mungu ila Wewe.", "Mara tatu asubuhi na jioni.", "Abu Bakrah (RA) alimsikia Mtume ﷺ akisema hivi."),
        "dua_sharri_sami" to DuaText("Kimbilio kutoka kwa Uovu wa Hisia Zangu", "Ewe Mwenyezi Mungu, najikinga Kwako kutokana na shari ya kusikia kwangu, na ubaya wa macho yangu, na ubaya wa ulimi wangu, na ubaya wa moyo wangu, na ubaya wa matamanio yangu.", "Alimfundisha Shakal ibn Humayd (RA).", "Dua ya kulinda viungo na nafsi na dhambi."),
        "dua_hadm_gharaq" to DuaText("Kimbilio dhidi ya Kifo cha Ghafla na Ajali", "Ewe Mwenyezi Mungu, najikinga Kwako nisivunjwe (na jengo), nisianguke kutoka juu, na kuzama, na kuungua na uzee; kutoka kwa Shetani akinipoteza wakati wa kufa, na kufa nikikimbia njia Yako, na kutokana na kufa kwa kuumwa (kwa sumu).", "Kimbilio kutoka kwa ajali na kifo mbaya.", "Dua ya kimbilio kutoka kwa Mtume ﷺ."),
        "dua_ju_khiyanah" to DuaText("Kimbilio dhidi ya Njaa na Usaliti", "Ewe Mwenyezi Mungu, mimi najikinga Kwako na njaa, kwani hiyo ni sahaba muovu, na najikinga Kwako kutokana na khiyana, kwani ni msiri mbaya.", "Kimbilio kutoka kwa njaa na usaliti.", "Dua ya kimbilio kutoka kwa Mtume ﷺ."),
        "dua_huda_tuqa" to DuaText("Mwongozo, Uchamungu, Usafi na Utoshelevu", "Ewe Mwenyezi Mungu, nakuomba uwongofu, uchamungu, usafi na kujitosheleza.", "Dua fupi na ya kina ya Mtume ﷺ.", "Baraka nne za msingi za dini na dunia hii."),
        "dua_aslih_li_dini" to DuaText("Rekebisha Dini Yangu, Dunia na Akhera", "Ewe Mwenyezi Mungu, nitengenezee dini yangu ambayo ndiyo ulinzi wa mambo yangu yote; Sahihisha maisha yangu ya dunia, ambayo ndani yake mna riziki yangu; na urekebishe Akhera yangu, ambayo kwayo nitarejea. Uniongezee uhai katika kila kheri, na unijaalie kifo kuwa ni nafuu ya kila shari.", "Kurekebisha dini, dunia na Akhera - zote tatu.", "Dua kamili ya Mtume ﷺ."),
        "dua_musarrifal_qulub" to DuaText("Ielekeze Mioyo Yetu kwa Utiifu Wako", "Ewe Mwenyezi Mungu, Mgeuza nyoyo, zielekeze nyoyo zetu kwenye utiifu wako.", "Dua ya kuuweka moyo imara katika utiifu.", "Nyoyo za watu wote ziko baina ya vidole viwili vya Mwingi wa Rehema."),
        "dua_jannah_nar" to DuaText("Kuomba Jannah, Kimbilio na Moto", "Ewe Mwenyezi Mungu, nakuomba Pepo na najikinga Kwako na Moto.", "Baada ya tashahhud au wakati wowote.", "Mtume ﷺ amesema: Dua zetu pia zinazunguka katika hili."),
        "dua_khayri_kullih" to DuaText("Yote Mzuri, Sasa na Baadaye", "Ewe Mwenyezi Mungu, mimi nakuomba kheri zote - za haraka na zilizochelewa, ninazozijua na nisizozijua - na najikinga Kwako na shari zote - za haraka na zilizochelewa, ninazozijua na nisizozijua. Ewe Mwenyezi Mungu, nakuomba Pepo na maneno na vitendo vyovyote vinavyonikaribia, na najikinga Kwako na Moto na kutokana na maneno na vitendo vyovyote vinavyonikaribia.", "Mtume ﷺ alifundisha dua hii ya kina kwa Aisha (RA) (sehemu ya dua).", "Dua inayokusanya kila jema."),
        "dua_ihdini_saddidni" to DuaText("Niongoze na Uniweke sawa", "Ewe Mwenyezi Mungu niongoze na uniweke kwenye njia iliyo sawa.", "Mtume ﷺ alimfundisha Ali (RA).", "Fikiria uwongofu kama kuongozwa njiani, na sadad kama unyofu wa mshale."),
        "dua_hubbaka" to DuaText("Kuomba Mapenzi ya Mwenyezi Mungu", "Ewe Mwenyezi Mungu, nakuomba upendo Wako, upendo wa wale wanaokupenda, na vitendo vinavyonifikisha kwenye mapenzi Yako. Ewe Mwenyezi Mungu, yajaalie mapenzi Yako kuwa makubwa kwangu kuliko mimi, familia yangu na maji baridi.", "Dua ya Dawud (AS) iliyosimuliwa na Mtume ﷺ.", "Mapenzi ya Mwenyezi Mungu ndio utajiri mkubwa."),
        "dua_filal_khayrat" to DuaText("Kufanya Mema na Kuacha Maovu", "Ewe Mwenyezi Mungu, nakuomba uniwezeshe kufanya vitendo vyema, kuacha maovu na kuwapenda masikini, na unisamehe na unirehemu. Na unapowatakia watu mtihani, basi nishike bila ya kujaribiwa. Ninakuomba upendo Wako, upendo wa wale wanaokupenda, na upendo wa vitendo vinavyonileta karibu na upendo Wako.", "Mwenyezi Mungu alimfundisha Mtume ﷺ dua hii katika ndoto.", "Mtume ﷺ amesema: ni kweli, basi jifunzeni na muifundishe."),
        "dua_bi_ilmikal_ghayb" to DuaText("Niache Niishi Wakati Maisha Ni Mazuri", "Ewe Mwenyezi Mungu, kwa ujuzi Wako wa ghaibu na uwezo Wako juu ya viumbe, niweke hai maadamu Unajua maisha ni bora kwangu, na nichukue unapojua kifo ni bora kwangu. Ewe Mwenyezi Mungu, nakuomba kwa khofu Yako kwa siri na hadharani, kwa neno la haki kwa kuridhika na kwa hasira, na wastani katika ufukara na mali.", "Dua ya maombi ya Ammar ibn Yasir (RA) (sehemu ya ufunguzi).", "Mtume ﷺ alifanya dua hii katika sala."),
        "dua_ism_azam_mannan" to DuaText("Ism-e-Azam: Al-Mannan", "Ewe Mwenyezi Mungu, nakuomba, kwani sifa njema zote ni Zako; hapana mungu ila Wewe, Mwingi wa rehema, Muumba wa mbingu na ardhi. Ewe Mwenye Ukuu na Heshima, Ewe Uliye hai, Ewe Mlinzi!", "Mtume ﷺ alisema mtu huyu alifanya dua kwa Jina kuu la Mwenyezi Mungu.", "Dua iliyofanywa kwa Jina hili inajibiwa."),
        "dua_ism_azam_ahad_samad" to DuaText("Ism-e-Azam: Al-Ahad As-Samad", "Ewe Mwenyezi Mungu, nakuomba, kwani nashuhudia kwamba Wewe ni Mwenyezi Mungu; hakuna mungu ila Wewe, Mmoja, Mjitosheleza, ambaye hazai wala hazaliwa, na hakuna anayelingana Naye.", "Mtume ﷺ alisema mtu huyu alimuuliza Mwenyezi Mungu kwa Jina Lake Kuu.", "Akiombwa nayo, hutoa; inapoitwa nayo, Yeye hujibu."),
        "dua_thabbitni_hadiyan" to DuaText("Nifanye Imara, Mwongozo na Mwongozo", "Ewe Mwenyezi Mungu, nijaalie niwe mwenye kuongoka na mwenye kuongoka.", "Mtume ﷺ alifanya dua hii kwa Jarir (RA) (kwa ajili yako mwenyewe sema 'thabbitni').", "Dua asili ya Jarir (RA) inatumia maneno 'thabbit-hu'."),
        "dua_rabbighfir_tub_alayya" to DuaText("Nisamehe na ukubali Toba yangu", "Mola wangu Mlezi, nisamehe na ukubali toba yangu. Hakika Wewe ni Mwenye kupokea toba, Mwenye kurehemu.", "Mara mia moja katika kikao kimoja - kitendo cha Mtume ﷺ.", "Maswahaba walimhesabu Mtume ﷺ akisema mara mia kwa kikao kimoja."),
        "dua_rafiq_ala" to DuaText("Dua ya Mtu Anayekufa", "Ewe Mwenyezi Mungu, nisamehe, nirehemu, na uniunganishe na Sahaba Mkuu.", "Dua ya mwisho ya Mtume ﷺ - kwa mgonjwa kusema kwa nafsi yake.", "Mtume ﷺ alifanya dua hii wakati wa kufa kwake."),
        "dua_la_bas_tahur" to DuaText("Kuwafariji Wagonjwa: Utakaso", "Hakuna madhara; ni utakaso (na dhambi), akipenda Mwenyezi Mungu.", "Ili kuwafariji wagonjwa wakati wa kuwatembelea.", "Mtume ﷺ alisema haya alipokuwa akiwatembelea wagonjwa."),
        "dua_talqeen" to DuaText("Talqeen kwa Wanaokufa", "Hapana apasae kuabudiwa kwa haki isipokuwa Mwenyezi Mungu.", "Soma kalimah karibu na mtu anayekufa (usilazimishe kusema).", "Yeyote ambaye maneno yake ya mwisho ni 'La ilaha illallah' ataingia Peponi (Abu Dawud 3116)."),
        "dua_ahyini_ma_kanat" to DuaText("Badala ya Kutakia Kifo", "Ewe Mwenyezi Mungu niweke hai maadamu maisha ni bora kwangu, na unifishe wakati kifo ni bora kwangu.", "Badala ya kutamani kifo katika shida.", "Mtume ﷺ alikataza kutamani kifo na badala yake akafundisha hivi."),
        "dua_for_one_i_cursed" to DuaText("Kwa Mtu Namuumiza kwa Maneno", "Ewe Mwenyezi Mungu, Muumini yeyote ambaye nimemtukana, mfanye kuwa ni njia ya kujikurubisha Kwako Siku ya Kiyama.", "Kwa mtu uliyeongea naye vibaya kwa hasira.", "Dua ya Mtume ﷺ."),
        "dua_praising_someone" to DuaText("Wakati wa Kumsifu Mtu", "Mimi naona fulani hivi kuwa hivi, na Mwenyezi Mungu ndiye Mwenye hisabu yake, wala simthibitishii mtu yeyote kutakasika mbele ya Mwenyezi Mungu.", "Wakati wa kumsifu mtu, badala ya kutia chumvi.", "Mtume ﷺ alifundisha adabu hii ya sifa."),
        "dua_being_praised" to DuaText("Unaposifiwa", "Ewe Mwenyezi Mungu, usinihesabie yale wayasemayo, na unisamehe wasiyoyajua.", "Kwa kusikia mtu akisifiwa - mazoezi ya Sahaba (RA).", "Njia ya kuepuka kiburi wakati wa kusifiwa."),
        "dua_non_muslim_sneezes" to DuaText("Asiye Muislamu Anapopiga Chafya", "Mwenyezi Mungu akuongoze na akutengenezee mambo yako.", "Wakati asiye Muislamu anapiga chafya na kusema 'Alhamdulillah'.", "Mayahudi walikuwa wakipiga chafya karibu na Mtume ﷺ wakitarajia angesema 'Yarhamukallah', na angesema hivi."),
        "dua_reply_ahl_kitab_salam" to DuaText("Kujibu Salamu za Watu wa Kitabu", "Na juu yako.", "Wanaposalimia Watu wa Kitabu kwa salamu.", "Maelekezo ya Mtume ﷺ."),
        "dua_fasting_invited" to DuaText("Unapoalikwa Ukiwa Umefunga", "Ninafunga.", "Unapoalikwa ukiwa umefunga, au mtu anapogombana nawe.", "Mfungaji akikubali mwaliko, anapaswa kumwombea mwenyeji."),
        "dua_for_who_gave_drink" to DuaText("Kwa Yeyote Aliyenilisha", "Ewe Mwenyezi Mungu mlishe yule aliyenilisha na mpe kinywaji aliyeninywesha.", "Kwa anayekupa chakula au kinywaji.", "Mtume ﷺ alifanya dua hii kwa al-Miqdad (RA)."),
        "dua_eid_greeting" to DuaText("Salamu za Eid", "Mwenyezi Mungu akubali (amali njema) kutoka kwetu na kwako.", "Kujumuika siku ya Idi - desturi ya Maswahaba watukufu (RA).", "Maswahaba walisema hivyo walipokutana siku ya Idi."),
        "dua_wedding_night" to DuaText("Kwa Bibi arusi Baada ya Nikah", "Ewe Mwenyezi Mungu ninakuomba kheri yake na kheri ya maumbile uliyomuumba nayo, na najikinga Kwako kutokana na shari yake na shari ya maumbile uliyomuumba nayo.", "Baada ya nikah, akiweka mkono kwenye paji la uso la mke.", "Mafundisho ya Mtume ﷺ - baraka katika ndoa."),
        "dua_istisqa_ibadak" to DuaText("Maji Watumishi na Wanyama Wako", "Ewe Mwenyezi Mungu wape maji waja Wako na wanyama Wako, ueneze rehema yako na uhuishe ardhi yako iliyokufa.", "Kuomba mvua (istisqa).", "Mtume ﷺ alifanya dua hii kwa ajili ya mvua."),
        "dua_seeing_clouds" to DuaText("Kuona Mawingu ya Giza", "Ewe Mwenyezi Mungu, najikinga Kwako kutokana na shari yake.", "Kwa kuona mawingu meusi angani; mvua ikinyesha sema 'Allahumma sayyiban nafi'a'.", "Akiona mawingu, Mtume ﷺ angeacha alichokuwa akifanya na kufanya dua hii."),
        "dua_jamarat" to DuaText("Kupiga mawe Jamarat", "Mwenyezi Mungu ndiye Mkubwa.", "Kwa kila kokoto iliyorushwa.", "Mtume ﷺ alisema takbir kwa kila kokoto, kisha baada ya jamrah ya kwanza na ya pili akaelekea Qiblah na akafanya dua ndefu."),
        "dua_rabbi_ainni" to DuaText("Mola wangu Mlezi, Nisaidie na Usiwe Dhidi Yangu", "Mola wangu Mlezi nisaidie wala usiwasaidie wengine dhidi yangu, nipe ushindi na usiwape wengine ushindi juu yangu, nipangie na usinipangie, niongoze na unifanyie wepesi uwongofu, na nisaidie dhidi ya anaye nidhulumu.", "Dua ya kina ya Mtume ﷺ (sehemu ya ufunguzi).", "Dua inayokusanya kila msaada katika dini na dunia."),
        "dua_ati_nafsi_taqwaha" to DuaText("Ijaalie Nafsi Yangu Taqwa", "Ewe Mwenyezi Mungu, ijaalie nafsi yangu uchamungu wake na uitakase, kwani Wewe ndiye mbora wa kuitakasa. Wewe ndiye Mlinzi wake na Mola wake.", "Kwa ajili ya kurekebisha na kutakasa nafsi.", "Mtume ﷺ alikuwa akifanya dua hii."),
        "dua_iqsim_lana_khashyatik" to DuaText("Utujalie Hofu Hiyo Yako", "Ewe Mwenyezi Mungu, tujaalie khofu ya kutosha kwako itufikie baina yetu na kukuasi, utii wa kutosha wa kutufikisha kwenye Pepo yako, na yakini ya kutosha ya kutufanya maafa ya dunia kuwa mepesi kwetu. Hebu tufurahie kusikia kwetu, macho yetu na nguvu zetu maadamu Umetuweka hai, na Utufanye ziwe mbali nasi. Lipize kisasi chetu kwa wale wanaotudhulumu, tusaidie dhidi ya maadui zetu, usiache balaa yetu iwe katika dini yetu, usiifanye dunia hii kuwa ni wasiwasi wetu mkubwa au kikomo cha elimu yetu, na usiweke juu yetu wale ambao hawatatuonea huruma.", "Wakati akiinuka kutoka kwenye mkusanyiko - Mtume ﷺ aliinuka mara chache bila kufanya dua hii.", "Dua kamili kwa kheri ya dini, dunia na Akhera."),
        "dua_infani_bima_allamtani" to DuaText("Nifaidi Kwa Uliyonifundisha", "Ewe Mwenyezi Mungu ninufaishe kwa yale uliyonifundisha, nifundishe yatakayonifaa, na nizidishie elimu.", "Wakati wa kutafuta maarifa au kabla ya kusoma.", "Dua ya elimu yenye manufaa na kuifanyia kazi."),
    )
}
